nuPeliculas() {    int opc;    while (true) {        system("cls");        cout << "========================================" << endl;        cout << "         GESTION DE PELICULAS           " << endl;        cout << "========================================" << endl;        cout << " 1 - AGREGAR PELICULA" << endl;        cout << " 2 - BAJA PELICULA" << endl;        cout << " 3 - MODIFICAR PELICULA" << endl;        cout << " 0 - VOLVER" << endl;        cout << "========================================" << endl;        cout << "INGRESE UNA OPCION: ";        cin >> opc;        system("cls");        switch (opc) {            case 1:                agregarPelicula();                break;            case 2:                bajaPelicula();                break;            case 3:                modificarPelicula();                break;            case 0:                return;            default:                cout << "OPCION NO VALIDA." << endl;                break;        }        system("pause");    }}void listarPeliculas() {    ArchivoPeliculas arc;    arc.listarRegistros();}void agregarPelicula() {    int id;    cout << "INGRESE EL ID DE LA PELICULA: ";    cin >> id;    if (id <= 0) {        cout << "EL ID INGRESADO NO ES VALIDO." << endl;        return;    }    ArchivoPeliculas arc;    int pos = arc.buscarRegistro(id);    if (pos >= 0) {        cout << "EL ID INGRESADO YA EXISTE EN EL ARCHIVO." << endl;        return;    }    Pelicula obj;    obj.setIdPelicula(id);    obj.Cargar();    if (arc.grabarRegistro(obj)) {        cout << "PELICULA GRABADA CON EXITO." << endl;    } else {        cout << "ERROR AL GRABAR LA PELICULA." << endl;    }}void bajaPelicula() {    int id;    cout << "INGRESE EL ID DE LA PELICULA A DAR DE BAJA: ";    cin >> id;    ArchivoPeliculas arc;    int pos = arc.buscarRegistro(id);    if (pos < 0) {        cout << "NO EXISTE LA PELICULA EN EL ARCHIVO." << endl;        return;    }    Pelicula obj = arc.leerRegistro(pos);    obj.setEstado(false);    if (arc.modificarRegistro(obj, pos)) {        cout << "PELICULA DADA DE BAJA CORRECTAMENTE." << endl;    } else {        cout << "ERROR AL MODIFICAR EL ARCHIVO." << endl;    }}void modificarPelicula() {    int id;    cout << "INGRESE EL ID DE LA PELICULA A MODIFICAR: ";    cin >> id;    ArchivoPeliculas arc;    int pos = arc.buscarRegistro(id);    if (pos < 0) {        cout << "NO EXISTE LA PELICULA EN EL ARCHIVO." << endl;        return;    }    Pelicula obj = arc.leerRegistro(pos);    char nuevoNombre[50];    cout << "INGRESE EL NUEVO NOMBRE DE LA PELICULA: ";    cin.ignore();    cin.getline(nuevoNombre, 50);    obj.setNombrePelicula(nuevoNombre);    if (arc.modificarRegistro(obj, pos)) {        cout << "PELICULA MODIFICADA CON EXITO." << endl;    } else {        cout << "ERROR AL MODIFICAR LA PELICULA." << endl;    }}//SUBMENÚ GÉNEROS (ABM)void menuGeneros() {    int opc;    while (true) {        system("cls");        cout << "========================================" << endl;        cout << "         GESTION DE GENEROS             " << endl;        cout << "========================================" << endl;        cout << " 1 - AGREGAR GENERO" << endl;        cout << " 2 - BAJA GENERO" << endl;        cout << " 3 - MODIFICAR GENERO" << endl;        cout << " 0 - VOLVER" << endl;        cout << "========================================" << endl;        cout << "INGRESE UNA OPCION: ";        cin >> opc;        system("cls");        switch (opc) {            case 1:                agregarTipoGenero();                break;            case 2:                bajaTipoGenero();                break;            case 3:                modificarTipoGenero();                break;            case 0:                return;            default:                cout << "OPCION NO VALIDA." << endl;                break;  